INSERT INTO `item` VALUES(77, 2, 0, 1, 'Ingoku Danchi', 'Aucun', 'https://cdn.myanimelist.net/images/anime/1373/155741.jpg', 'https://voir-anime.to/anime/ingoku-danchi/ingoku-danchi-deviants-apartment-complex-{ep2}-vostfr/', 'ok', 'Yoshida jeune diplômé, petit et frêle, se retrouve à la tête d\'un immeuble d\'appartements contre son gré lorsque son père, l\'ancien gérant, se blesse. À son insu, cet immeuble abrite pas mal de femmes aux préférences sexuelles pour le moins… inhab...', '1', 1, 4, NULL, '2026-07-27 14:51:07', '2026-07-27 10:44:23', '2026-07-27 14:51:07');
INSERT INTO `item` VALUES(78, 5, 0, 4, 'Soy Luna', 'En cours', 'https://image.tmdb.org/t/p/w500/4JDmIzhNF7aMsDGlxVwkQ9kv9E6.jpg', 'https://nakastream.tv/player?title=Soy%20Luna&id=8332&poster=/4JDmIzhNF7aMsDGlxVwkQ9kv9E6.jpg&type=tv&season={s}&episode={ep}', 'ok', 'Luna glisse avec bonheur sur la vie comme sur ses rollers ! Comme toutes les jeunes filles de son âge, elle vit avec sa famille entourée d’amis et découvre la vie entre ses cours et son job de serveuse. Mais ce qu’elle aime par-dessus tout, c’est ...', '10', 1, 0, NULL, NULL, '2026-08-10 20:37:29', '2026-08-11 08:36:07');
INSERT INTO `item` VALUES(79, 2, 0, 3, 'Oppenheimer', 'En pause', 'https://image.tmdb.org/t/p/w500/boAUuJBeID7VNp4L7LNMQs8mfQS.jpg', 'https://nakastream.tv/player?title=Oppenheimer&id=1065&poster=/boAUuJBeID7VNp4L7LNMQs8mfQS.jpg&type=movie', 'ok', 'Temps : 1:00:00', NULL, NULL, 1, NULL, NULL, '2026-08-10 21:11:30', '2026-08-10 21:32:07');
INSERT INTO `item` VALUES(80, 5, 0, 4, 'The Rookie : Le Flic de Los Angeles', 'En cours', 'https://image.tmdb.org/t/p/w500/aOXBLBRg7M5D2Zrs5luKD5cDB8O.jpg', 'https://nakastream.tv/player?id=334&title=The+Rookie+%3A+Le+Flic+de+Los+Angeles&type=tv&poster=%2FaOXBLBRg7M5D2Zrs5luKD5cDB8O.jpg&season={s}&episode={ep}&backdrop=%2F6iNWfGVCEfASDdlNb05TP5nG0ll.jpg', 'ok', 'John Nolan, le rookie le plus âgé du LAPD, utilise son expérience de vie, sa détermination et son sens de l’humour pour suivre des recrues âgées de 20 ans de moins que lui.', '2', 2, 1, NULL, NULL, '2026-08-11 00:05:24', '2026-08-11 00:05:24');
INSERT INTO `item` VALUES(81, 5, 0, 4, 'Violetta', 'À voir', 'https://image.tmdb.org/t/p/w500/b3MUGJeKakAZwQa7lNJxTP1pJmD.jpg', '', 'ok', 'Violetta, c\'est l\'histoire d\'une adolescente très talentueuse qui, après avoir vécu de nombreuses années à Madrid, est retournée avec son père à Buenos Aires, sa ville natale. Elle entrera dans un studio de musique, mais suscitera la jalousie de L...', '1', 1, 2, NULL, NULL, '2026-08-11 00:09:56', '2026-08-11 00:09:56');
